import{_ as r,C as s,o as d,c as e,a2 as n,j as i,E as l,a as t}from"./chunks/framework.C21TwvGF.js";const D=JSON.parse(`{"title":"21-dars (Mentor). Flowalgorithm interfeysi va blok-sxema elementlari bilan ishlash","description":"","frontmatter":{"title":"21-dars (Mentor). Flowalgorithm interfeysi va blok-sxema elementlari bilan ishlash","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"week":{"n":7,"link":"/mentor/8-sinf-cs/hafta-07/"},"g":21,"title":"Flowalgorithm interfeysi va blok-sxema elementlari bilan ishlash","lead":"Dasturlashni o'rganishda harf terib charchash shart emas! Flowgorithm vizual dasturida bloklarni bir-biriga ulab, haqiqiy ishlaydigan dastur yaratishingiz mumkin. Bugun birinchi blok-sxemamizni chizamiz va uni ishga tushiramiz!","slide":"/slaydlar/8-sinf-cs/hafta-07/dars-3.html","test":"/slaydlar/8-sinf-cs/hafta-07/dars-3-test.html","student_link":"/8-sinf-cs/hafta-07/dars-3","tabs":[{"g":19,"link":"/mentor/8-sinf-cs/hafta-07/dars-1","current":false},{"g":20,"link":"/mentor/8-sinf-cs/hafta-07/dars-2","current":false},{"g":21,"link":"/mentor/8-sinf-cs/hafta-07/dars-3","current":true}],"prev":{"g":20,"title":"Algoritm tushunchasi va algoritmik fikrlash","link":"/mentor/8-sinf-cs/hafta-07/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-07/dars-3.md","filePath":"mentor/8-sinf-cs/hafta-07/dars-3.md"}`),h={name:"mentor/8-sinf-cs/hafta-07/dars-3.md"},u={class:"blk"},m={id:"darsning-maqsadi",tabindex:"-1"},g={class:"blk"},b={id:"kutiladigan-natija",tabindex:"-1"},k={class:"blk"},c={id:"kerakli-jihozlar",tabindex:"-1"},q={class:"blk"},y={id:"dars-rejasi-80-daqiqa",tabindex:"-1"},v={class:"blk"},p={id:"konspekt-mentor-aytadigan-matn",tabindex:"-1"},f={class:"blk"},z={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},x={class:"blk"},_={id:"tezkor-nazorat-savollari",tabindex:"-1"},S={class:"blk"},F={id:"uyga-vazifa",tabindex:"-1"};function T(I,a,O,P,j,A){const o=s("Icon");return d(),e("div",null,[a[25]||(a[25]=n("<p><strong>Fan:</strong> Computer Science Foundation<br><strong>Sinf:</strong> 8-sinf<br><strong>Hafta:</strong> 7-hafta, 3-dars (umumiy 21-dars)<br><strong>Davomiyligi:</strong> 80 daqiqa<br><strong>Bob:</strong> III-bob. Algoritmlash, Flowalgorithm va dasturlash asoslari (2-dars)<br><strong>Manba:</strong> O&#39;quv dasturi, III-bob: «Flowalgorithm interfeysi va blok-sxema elementlari bilan ishlash. Flowalgorithm dasturi interfeysi va ishchi oynasi bilan tanishish. Blok-sxema elementlari: Start, End, Input, Output, Process, Decision. Bloklarni joylashtirish, ulash va algoritm ketma-ketligini qurish. Oddiy algoritm yaratish, ishga tushirish va natijani tekshirish. Blok-sxemadagi xatolarni aniqlash va tuzatish.»</p><hr>",2)),i("div",u,[i("h2",m,[l(o,{name:"file-text"}),a[0]||(a[0]=t(" Darsning maqsadi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#darsning-maqsadi","aria-label":'Permalink to "<Icon name="file-text" /> Darsning maqsadi"'},"​",-1))]),a[2]||(a[2]=i("p",null,"O'quvchilarni Flowgorithm (Flowalgorithm) vizual dasturlash muhiti bilan tanishtirish; uning ishchi oynasi, boshqaruv tugmalari va asosiy blok-sxema elementlarini (Start, End, Input, Output, Process, Decision) o'rgatish; bloklarni to'g'ri joylashtirish, bog'lash, oddiy algoritmlarni ishga tushirish va xatolarni tuzatish ko'nikmalarini shakllantirish.",-1))]),i("div",g,[i("h2",b,[l(o,{name:"file-text"}),a[3]||(a[3]=t(" Kutiladigan natija ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#kutiladigan-natija","aria-label":'Permalink to "<Icon name="file-text" /> Kutiladigan natija"'},"​",-1))]),a[5]||(a[5]=i("ul",null,[i("li",null,"Flowgorithm dasturining nima uchun kerakligini va uning qulayliklarini biladi;"),i("li",null,"Dastur interfeysi: ishchi maydon, Run (F5), Step by step (F6), Console va Source Code oynalaridan foydalana oladi;"),i("li",null,"Blok-sxema asosiy elementlarini (Start/End, Input, Output, Process, Decision) shakli, rangi va vazifasiga ko'ra ajratadi;"),i("li",null,"Start va End orasiga blok joylashtirib, unga parametr yozishni (matnni qo'shtirnoqqa olishni) biladi;"),i("li",null,"Oddiy salomlashuv va ma'lumot kiritish-chiqarish algoritmini xatosiz tuzib, konsolda natijani ko'ra oladi.")],-1))]),i("div",k,[i("h2",c,[l(o,{name:"file-text"}),a[6]||(a[6]=t(" Kerakli jihozlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#kerakli-jihozlar","aria-label":'Permalink to "<Icon name="file-text" /> Kerakli jihozlar"'},"​",-1))]),a[8]||(a[8]=i("ul",null,[i("li",null,"O'quvchilar kompyuteri (Flowgorithm dasturi o'rnatilgan holda)"),i("li",null,"Proyektor va ekran (namoyish uchun)"),i("li",null,"O'quvchi daftari va qalam")],-1)),a[9]||(a[9]=i("hr",null,null,-1))]),i("div",q,[i("h2",y,[l(o,{name:"file-text"}),a[10]||(a[10]=t(" Dars rejasi (80 daqiqa) ",-1)),a[11]||(a[11]=i("a",{class:"header-anchor",href:"#dars-rejasi-80-daqiqa","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi (80 daqiqa)"'},"​",-1))]),a[12]||(a[12]=n('<table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>00–08</td><td>Takrorlash</td><td>20-dars (Algoritm tushunchasi va 5 ta xossa)</td></tr><tr><td>08–25</td><td>Yangi mavzu 1</td><td>Flowgorithm nima? Dastur interfeysi va boshqaruv paneli</td></tr><tr><td>25–42</td><td>Yangi mavzu 2</td><td>Blok-sxema elementlari: Start/End, Output, Input, Process, Decision</td></tr><tr><td>42–47</td><td>Tanaffus</td><td>Qisqa dam olish</td></tr><tr><td>47–60</td><td>Yangi mavzu 3</td><td>Birinchi blok-sxema, Step-by-Step bajarish va xatolarni tahlil qilish</td></tr><tr><td>60–75</td><td>Amaliyot</td><td>Kompyuterda 3 ta amaliy mashq (Salom dunyo, Ism kiritish, Xatoni tuzatish)</td></tr><tr><td>75–80</td><td>Xulosa</td><td>Tezkor nazorat savollari, hafta xulosasi, baholash</td></tr></tbody></table><hr>',2))]),i("div",v,[i("h2",p,[l(o,{name:"file-text"}),a[13]||(a[13]=t(" Konspekt (mentor aytadigan matn) ",-1)),a[14]||(a[14]=i("a",{class:"header-anchor",href:"#konspekt-mentor-aytadigan-matn","aria-label":'Permalink to "<Icon name="file-text" /> Konspekt (mentor aytadigan matn)"'},"​",-1))]),a[15]||(a[15]=n('<h3 id="_1-flowgorithm-nima-va-nega-u-qulay" tabindex="-1">1. Flowgorithm nima va nega u qulay? <a class="header-anchor" href="#_1-flowgorithm-nima-va-nega-u-qulay" aria-label="Permalink to &quot;1. Flowgorithm nima va nega u qulay?&quot;">​</a></h3><p>O&#39;tgan darsda algoritmni so&#39;zlar bilan yozishni o&#39;rgandik. Lekin dasturlashni boshlaganda birdaniga murakkab kod yozish (nuqta-vergul, qavslar, sintaksis qoidalari) yangi boshlovchini chalg&#39;itishi mumkin.</p><p>Shuning uchun butun dunyoda dasturlash mantiqini o&#39;rganish uchun <strong>Flowgorithm</strong> (o&#39;quv dasturimizda Flowalgorithm) vizual dasturidan foydalaniladi!</p><ul><li><strong>Vizual dasturlash:</strong> Kod yozish o&#39;rniga rang-barang blok-sxemalarni joylashtirasiz.</li><li><strong>Interaktiv tekshirish:</strong> Algoritmni bir tugma bilan (Run) ishga tushirasiz va u xuddi haqiqiy dastur kabi ishlaydi.</li><li><strong>Qadamma-qadam rejim (Step by Step):</strong> Algoritm qanday yurishini qadam-baqadam ko&#39;rib, xatolarni oson topasiz.</li><li><strong>Ko&#39;p tilli kod generatori:</strong> Chizgan blok-sxemangizni bir zumda Python, C++, Java yoki JavaScript kodiga o&#39;girib ko&#39;rsatib beradi!</li></ul><p><strong>Interfeys bilan tanishuv:</strong></p><ol><li><strong>Asosiy ish maydoni:</strong> Markazda doimo ikkita blok turadi: <code>Main</code> (Start) va <code>End</code>.</li><li><strong>Asboblar paneli:</strong><ul><li><strong>Run (Yashil uchburchak / F5):</strong> Dasturni to&#39;liq ishga tushirish.</li><li><strong>Step (Qadam / F6):</strong> Har bir blokni navbati bilan ko&#39;k rangda yoritib, bittalab bajarish.</li><li><strong>Tezlik slayderi (Speed):</strong> Qadamlar tezligini sekinlashtirish yoki tezlashtirish.</li><li><strong>Console (Konsol oynasi):</strong> Dastur chiqargan matnlar va foydalanuvchi kiritadigan maydon.</li><li><strong>Source Code Viewer:</strong> Sxemaning real dasturlash tillaridagi kodini ko&#39;rish.</li></ul></li></ol><h3 id="_2-blok-sxema-elementlari-va-ularning-vazifalari" tabindex="-1">2. Blok-sxema elementlari va ularning vazifalari <a class="header-anchor" href="#_2-blok-sxema-elementlari-va-ularning-vazifalari" aria-label="Permalink to &quot;2. Blok-sxema elementlari va ularning vazifalari&quot;">​</a></h3><p>Flowgorithmda har bir amal o&#39;zining maxsus shakli va rangiga ega:</p><table tabindex="0"><thead><tr><th>Blok nomi</th><th>Geometrik shakli</th><th>Rangi</th><th>Vazifasi va namunasi</th></tr></thead><tbody><tr><td><strong>Start / End</strong></td><td>Yumaloq to&#39;rtburchak (Oval)</td><td>Yashil / Qizil</td><td>Dasturning boshlanishi va tugashini bildiradi</td></tr><tr><td><strong>Output (Chiqarish)</strong></td><td>Parallelogramm</td><td>Yashil</td><td>Ekranga matn yoki son chiqaradi. Matnlar qo&#39;shtirnoqda: <code>&quot;Salom!&quot;</code></td></tr><tr><td><strong>Input (Kiritish)</strong></td><td>Parallelogramm</td><td>Moviy</td><td>Klaviaturadan ma&#39;lumot kiritib, o&#39;zgaruvchida saqlaydi</td></tr><tr><td><strong>Process / Assign (Hisoblash)</strong></td><td>To&#39;g&#39;ri to&#39;rtburchak</td><td>Sariq</td><td>Qiymat berish va matematik hisoblash: <code>Summa = A + B</code></td></tr><tr><td><strong>Decision / If (Shart)</strong></td><td>Romb (Olmos)</td><td>Sariq / Zarg&#39;aldoq</td><td>Shartni tekshiradi: Ha (True) yoki Yo&#39;q (False) tarmoqlari</td></tr><tr><td><strong>Loop (Sikl)</strong></td><td>Oltiburchak / Romb</td><td>Qizg&#39;ish</td><td>Takrorlanuvchi jarayonlar uchun</td></tr></tbody></table><h3 id="_3-blok-qo-shish-va-birinchi-dasturni-tuzish" tabindex="-1">3. Blok qo&#39;shish va birinchi dasturni tuzish <a class="header-anchor" href="#_3-blok-qo-shish-va-birinchi-dasturni-tuzish" aria-label="Permalink to &quot;3. Blok qo&#39;shish va birinchi dasturni tuzish&quot;">​</a></h3><p>Blok qo&#39;shish qoidasi:</p><ol><li><code>Main</code> va <code>End</code> orasidagi yo&#39;naltiruvchi strelka (chiziq) ustiga sichqonchaning chap tugmasini bosing.</li><li>Ochilgan menyudan kerakli blokni tanlang (masalan, <code>Output</code>).</li><li>O&#39;rnatilgan blok ustiga ikki marta bosing.</li><li>Ichiga ifodani yozing: matn bo&#39;lsa <strong>albatta qo&#39;shtirnoq ichida</strong> bo&#39;lishi kerak: <code>&quot;Muhammad al-Xorazmiy vorislari!&quot;</code>.</li><li><code>OK</code> tugmasini bosing.</li><li>Yuqoridagi <strong>Run (F5)</strong> tugmasini bosing. Konsol oynasida matn paydo bo&#39;ladi!</li></ol><p><strong>Ko&#39;p uchraydigan xatolar va ularni tuzatish:</strong></p><ul><li><em>Xato:</em> Qo&#39;shtirnoqsiz yozish: <code>Salom</code>. Flowgorithm buni matn emas, e&#39;lon qilinmagan o&#39;zgaruvchi deb o&#39;ylaydi va qizil xato xabarini beradi.</li><li><em>Tuzatish:</em> Matnlarni doim <code>&quot;qo&#39;shtirnoq&quot;</code> ichiga oling. O&#39;zgaruvchi nomlarini esa qo&#39;shtirnoqsiz yozing.</li></ul><hr>',15))]),i("div",f,[i("h2",z,[l(o,{name:"file-text"}),a[16]||(a[16]=t(" Amaliy topshiriqlar va yechimlar ",-1)),a[17]||(a[17]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[18]||(a[18]=n('<h3 id="_1-topshiriq-«salom-dunyo-»-birinchi-blok-sxemasi-oson" tabindex="-1">1-topshiriq: «Salom, dunyo!» birinchi blok-sxemasi (Oson) <a class="header-anchor" href="#_1-topshiriq-«salom-dunyo-»-birinchi-blok-sxemasi-oson" aria-label="Permalink to &quot;1-topshiriq: «Salom, dunyo!» birinchi blok-sxemasi (Oson)&quot;">​</a></h3><p>Flowgorithm dasturida Start va End orasiga bitta Output blokini qo&#39;shib, ekranga <code>&quot;Salom, dunyo!&quot;</code> matnini chiqaring. Dasturni F5 bilan ishga tushiring, so&#39;ngra F6 (Step) yordamida qadamma-qadam bajarilishini kuzating.</p><p><strong>Kutiladigan natija:</strong> Konsolda yashil fonda «Salom, dunyo!» yozuvining paydo bo&#39;lishi.</p><p><strong>Yechim:</strong></p><ol><li>Yangi loyiha ochiladi.</li><li><code>Main</code> va <code>End</code> orasidagi strelka bosiladi.</li><li><code>Output</code> bloki tanlanadi.</li><li>Blok ichiga <code>&quot;Salom, dunyo!&quot;</code> deb yoziladi va <code>OK</code> bosiladi.</li><li>F6 tugmasi bosiladi: Main bloki yashil bo&#39;ladi, keyin F6 yana bosiladi: Output bloki ko&#39;k rangda faollashadi va konsolda yozuv chiqadi, so&#39;ngra End bloki bilan dastur tugaydi.</li></ol><hr><h3 id="_2-topshiriq-foydalanuvchi-bilan-salomlashish-o-rta" tabindex="-1">2-topshiriq: Foydalanuvchi bilan salomlashish (O&#39;rta) <a class="header-anchor" href="#_2-topshiriq-foydalanuvchi-bilan-salomlashish-o-rta" aria-label="Permalink to &quot;2-topshiriq: Foydalanuvchi bilan salomlashish (O&#39;rta)&quot;">​</a></h3><p>Foydalanuvchidan ismini so&#39;rab, unga <code>&quot;Xush kelibsiz, [Ism]!&quot;</code> deb javob qaytaruvchi algoritm tuzing. <em>Eslatma:</em> O&#39;zgaruvchi <code>ism</code> deb nomlanadi va matn turi (String) bo&#39;ladi.</p><p><strong>Kutiladigan natija:</strong> Ekran so&#39;rov chiqaradi, foydalanuvchi ism kiritadi va unga shaxsiy tabrik chiqadi.</p><p><strong>Yechim:</strong> Blok-sxema ketma-ketligi:</p><ol><li><code>Main</code> (Start)</li><li><code>Declare</code> bloki: Variable <code>ism</code>, Type <code>String</code></li><li><code>Output</code> bloki: <code>&quot;Ismingizni kiriting:&quot;</code></li><li><code>Input</code> bloki: <code>ism</code></li><li><code>Output</code> bloki: <code>&quot;Xush kelibsiz, &quot; &amp; ism &amp; &quot;!&quot;</code> (Flowgorithmda matnlarni ulash uchun <code>&amp;</code> belgisi ishlatiladi)</li><li><code>End</code><em>Sinov:</em> Konsolda <code>Ali</code> kiritilsa, natija: <code>Xush kelibsiz, Ali!</code>.</li></ol><hr><h3 id="_3-topshiriq-xatoni-topish-va-tuzatish-qiyin" tabindex="-1">3-topshiriq: Xatoni topish va tuzatish (Qiyin) <a class="header-anchor" href="#_3-topshiriq-xatoni-topish-va-tuzatish-qiyin" aria-label="Permalink to &quot;3-topshiriq: Xatoni topish va tuzatish (Qiyin)&quot;">​</a></h3><p>O&#39;quvchi ikkita sonning yig&#39;indisini chiqarmoqchi bo&#39;lib, Output blokiga quyidagicha yozdi: <code>Output: 5 + 10 = 15</code>. Lekin Flowgorithm qizil xatolik xabarini berdi. Nima uchun xato berdi va uni qanday to&#39;g&#39;rilash kerak?</p><p><strong>Kutiladigan natija:</strong> Tenglik belgisi va matn ifodalash xatosini tushuntirish hamda to&#39;g&#39;ri formulani taqdim etish.</p><p><strong>Yechim:</strong></p><ul><li><em>Xato sababi:</em> Flowgorithm <code>5 + 10 = 15</code> ifodasini matematik tenglama yoki taqqoslash deb tushunadi. Output bloki ichida tenglik belgisi bilan qiymat kiritilmaydi.</li><li><em>To&#39;g&#39;rilash varianti 1 (Faqat hisoblash):</em> <code>Output: 5 + 10</code> (Ekranga <code>15</code> chiqadi).</li><li><em>To&#39;g&#39;rilash varianti 2 (Matn va hisobni ulash):</em> <code>Output: &quot;5 + 10 = &quot; &amp; (5 + 10)</code> (Ekranga aniq <code>5 + 10 = 15</code> matni chiqadi).</li></ul><hr>',18))]),i("div",x,[i("h2",_,[l(o,{name:"file-text"}),a[19]||(a[19]=t(" Tezkor nazorat savollari ",-1)),a[20]||(a[20]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[21]||(a[21]=n("<ol><li><strong>Flowgorithmda ma&#39;lumotni ekranga chiqarish uchun qaysi blok ishlatiladi?</strong><br><em>Javob:</em> Yashil rangli parallelogramm shaklidagi <code>Output</code> bloki.</li><li><strong>Output blokida oddiy matn qanday belgilar ichida yozilishi shart?</strong><br><em>Javob:</em> Qo&#39;shtirnoqlar (<code>&quot;...&quot;</code>) ichida.</li><li><strong>F5 va F6 tugmalarining farqi nima?</strong><br><em>Javob:</em> F5 dasturni to&#39;liq birdaniga ishga tushiradi (Run), F6 esa har bir blokni bosqichma-bosqich bajaradi (Step).</li><li><strong>Input blokining vazifasi nima?</strong><br><em>Javob:</em> Foydalanuvchidan klaviatura orqali ma&#39;lumot qabul qilib olish va uni o&#39;zgaruvchida saqlash.</li></ol><hr>",2))]),i("div",S,[i("h2",F,[l(o,{name:"house"}),a[22]||(a[22]=t(" Uyga vazifa ",-1)),a[23]||(a[23]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[24]||(a[24]=i("ol",null,[i("li",null,"Flowgorithm dasturida sevimli kitobingiz yoki maktabingiz nomini ekranga 3 xil rang-barang qatorda chiqaruvchi blok-sxema loyihasini chizing."),i("li",null,[t("Sxemani rasmga olib yoki daftarga geometrik shakllar bilan chizib keling (batafsil: "),i("code",null,"uyga-vazifa.md"),t(").")])],-1))])])}const E=r(h,[["render",T]]);export{D as __pageData,E as default};
